from collections import deque


class FrontMiddleBackQueue:
    def __init__(self):
        self.left = deque()
        self.right = deque()

    def _rebalance(self):
        if len(self.left) > len(self.right) + 1:
            self.right.appendleft(self.left.pop())
        elif len(self.right) > len(self.left):
            self.left.append(self.right.popleft())

    def push_front(self, val):
        self.left.appendleft(val)
        self._rebalance()

    def push_middle(self, val):
        if len(self.left) > len(self.right):
            self.right.appendleft(self.left.pop())
        self.left.append(val)
        self._rebalance()

    def push_back(self, val):
        self.right.append(val)
        self._rebalance()

    def pop_front(self):
        if not self.left and not self.right:
            return -1
        val = self.left.popleft() if self.left else self.right.popleft()
        self._rebalance()
        return val

    def pop_middle(self):
        if not self.left and not self.right:
            return -1
        val = self.left.pop() if len(self.left) >= len(self.right) else self.right.popleft()
        self._rebalance()
        return val

    def pop_back(self):
        if not self.left and not self.right:
            return -1
        val = self.right.pop() if self.right else self.left.pop()
        self._rebalance()
        return val


