using namespace std;

class FrontMiddleBackQueue {
public:
    deque<int> left, right;

    void rebalance() {
        if (left.size() > right.size() + 1) {
            right.push_front(left.back());
            left.pop_back();
        } else if (right.size() > left.size()) {
            left.push_back(right.front());
            right.pop_front();
        }
    }

    void pushFront(int val) {
        left.push_front(val);
        rebalance();
    }

    void pushMiddle(int val) {
        if (left.size() > right.size()) {
            right.push_front(left.back());
            left.pop_back();
        }
        left.push_back(val);
        rebalance();
    }

    void pushBack(int val) {
        right.push_back(val);
        rebalance();
    }

    int popFront() {
        if (left.empty() && right.empty()) return -1;
        int val;
        if (!left.empty()) { val = left.front(); left.pop_front(); }
        else { val = right.front(); right.pop_front(); }
        rebalance();
        return val;
    }

    int popMiddle() {
        if (left.empty() && right.empty()) return -1;
        int val;
        if (left.size() >= right.size()) { val = left.back(); left.pop_back(); }
        else { val = right.front(); right.pop_front(); }
        rebalance();
        return val;
    }

    int popBack() {
        if (left.empty() && right.empty()) return -1;
        int val;
        if (!right.empty()) { val = right.back(); right.pop_back(); }
        else { val = left.back(); left.pop_back(); }
        rebalance();
        return val;
    }
};

